window.WeddingEffects=(()=>{let timer=null;function stop(){if(timer)clearInterval(timer);timer=null;document.querySelectorAll('.fx').forEach(x=>x.remove())}function start(type){stop();if(!type||type==='none')return;const layer=document.getElementById('fxLayer');if(!layer)return;const chars={hearts:['♥','♡'],petals:['✿','❀','❁'],snow:['❄','•'],glitter:['✦','✧','⋆'],stars:['★','✦','☆']}[type]||['✦'];timer=setInterval(()=>{const e=document.createElement('span');e.className='fx';e.textContent=chars[Math.floor(Math.random()*chars.length)];e.style.left=Math.random()*100+'vw';e.style.fontSize=(12+Math.random()*22)+'px';e.style.setProperty('--drift',(-80+Math.random()*160)+'px');e.style.animationDuration=(5+Math.random()*7)+'s';layer.appendChild(e);setTimeout(()=>e.remove(),13000)},380)}return{start,stop}})();
